import { layoutWinFlights } from '../app/win-flight-layout.js';

const active = new WeakMap();
const prepared = new WeakMap();
export function clearWinFlights(quad) { active.get(quad)?.(); }

const batches = new WeakMap();

function measureFlight(job) {
  const { quad, center } = job;
  const bounds = quad.getBoundingClientRect();
  const width = quad.clientWidth, height = quad.clientHeight;
  if (!width || !height || !bounds.width || !bounds.height) return false;
  const sx = width / bounds.width, sy = height / bounds.height;
  const local = node => {
    const r = node.getBoundingClientRect();
    return { left: (r.left - bounds.left) * sx, top: (r.top - bounds.top) * sy, width: r.width * sx, height: r.height * sy };
  };
  job.area = { left: 3, right: width - 3, top: 3, bottom: height - 3 };
  job.obstacles = [center, quad.querySelector('.replay-win-description'), quad.querySelector('.replay-badge-overflow-label')]
    .filter(Boolean).map(local);
  job.entries = [...quad.querySelectorAll('.replay-badge-wrap')].flatMap(badge => {
    const reward = badge.querySelector('.replay-badge-reward-pop');
    if (!reward) return [];
    const label = reward.cloneNode(true);
    label.className = 'replay-win-flight';
    label.style.maxWidth = `${width - 6}px`;
    const r = local(badge);
    return [{ badge, label, x: r.left + r.width / 2, y: r.top + r.height / 2 }];
  });
  return true;
}

function flushFlights(batch) {
  batch.frame = null;
  const jobs = [...batch.jobs.values()];
  batch.jobs.clear();
  const ready = jobs.filter(job => {
    if (job.quad.isConnected && measureFlight(job)) return true;
    job.cleanup();
    return false;
  });
  // Read all quadrant/badge bounds, mount all hidden labels, measure all labels,
  // then position them. Every quadrant shares the same preparation passes.
  for (const job of ready) {
    const fragment = job.quad.ownerDocument.createDocumentFragment();
    for (const { label } of job.entries) fragment.appendChild(label);
    job.quad.appendChild(fragment);
  }
  for (const { entries } of ready) for (const entry of entries) {
    entry.width = entry.label.offsetWidth;
    entry.height = entry.label.offsetHeight;
  }
  for (const job of ready) {
    const positions = layoutWinFlights(job.entries, job.area, job.obstacles);
    job.lastDelay = 0;
    job.entries.forEach((entry, index) => {
      const p = positions[index];
      if (!p) { entry.label.remove(); return; }
      job.lastDelay = Math.max(job.lastDelay, p.delay);
      entry.positioned = true;
      entry.label.style.left = `${p.left}px`;
      entry.label.style.top = `${p.top}px`;
      entry.label.style.setProperty('--flight-x', `${entry.x - p.left - entry.width / 2}px`);
      entry.label.style.setProperty('--flight-y', `${entry.y - p.top - entry.height / 2}px`);
      for (const node of [entry.label, entry.badge]) node.style.setProperty('--flight-delay', `${p.delay}ms`);
    });
    job.ready = true;
    if (job.requested) startFlight(job);
  }
}

function startFlight(job) {
  if (job.timer !== null) return;
  for (const entry of job.entries) {
    if (!entry.positioned) continue;
    entry.label.classList.add('is-flying');
    entry.badge.classList.add('replay-win-flight-source');
  }
  job.timer = job.view.setTimeout(job.cleanup, job.lastDelay + 1300);
}

/** Stage hidden labels and their final geometry while the reel is spinning. */
export function prepareWinFlights(quad, center) {
  clearWinFlights(quad);
  const view = quad.ownerDocument.defaultView;
  if (view.matchMedia?.('(prefers-reduced-motion: reduce)').matches) return;
  let batch = batches.get(view);
  if (!batch) { batch = { jobs: new Map(), frame: null }; batches.set(view, batch); }
  const job = { quad, center, view, entries: [], timer: null, cleanup: null, ready: false, requested: false, lastDelay: 0 };
  job.cleanup = () => {
    if (job.timer !== null) view.clearTimeout(job.timer);
    batch.jobs.delete(quad);
    if (!batch.jobs.size && batch.frame !== null) {
      view.cancelAnimationFrame(batch.frame);
      batch.frame = null;
    }
    for (const { label, badge } of job.entries) {
      label.remove(); badge.classList.remove('replay-win-flight-source');
      badge.style.removeProperty('--flight-delay');
    }
    delete quad.dataset.flying;
    view.removeEventListener('resize', resize);
    prepared.delete(quad);
    active.delete(quad);
  };
  const resize = () => {
    job.cleanup();
    if (quad.isConnected && !quad.classList.contains('q-result-revealed')) prepareWinFlights(quad, center);
  };
  prepared.set(quad, job);
  active.set(quad, job.cleanup);
  view.addEventListener('resize', resize, { once: true });
  batch.jobs.set(quad, job);
  if (batch.frame === null) batch.frame = view.requestAnimationFrame(() => flushFlights(batch));
}

/** Revealing only starts the already-positioned effects. A just-skipped spin
 * can join an in-flight preparation; it never starts another geometry pass. */
export function launchWinFlights(quad, center) {
  if (!prepared.has(quad)) prepareWinFlights(quad, center);
  const job = prepared.get(quad);
  if (!job) return;
  job.requested = true;
  quad.dataset.flying = 'true';
  if (job.ready) startFlight(job);
}

/** Keep a manually inspected prize beside its badge, clear of the total and seal. */
export function positionBadgeReward(badge, center) {
  const quad = badge.parentElement;
  const reward = badge.querySelector('.replay-badge-reward-pop');
  if (!quad?.clientWidth || !reward) return;
  const bounds = quad.getBoundingClientRect();
  const sx = quad.clientWidth / bounds.width, sy = quad.clientHeight / bounds.height;
  const local = node => {
    const r = node.getBoundingClientRect();
    return { left: (r.left - bounds.left) * sx, top: (r.top - bounds.top) * sy, width: r.width * sx, height: r.height * sy };
  };
  reward.style.maxWidth = `${quad.clientWidth - 6}px`;
  const source = local(badge);
  const item = { x: source.left + source.width / 2, y: source.top + source.height / 2,
    width: reward.offsetWidth, height: reward.offsetHeight };
  const obstacles = [center, quad.querySelector('.replay-win-description')].filter(Boolean).map(local);
  const [position] = layoutWinFlights([item], { left: 3, top: 3, right: quad.clientWidth - 3, bottom: quad.clientHeight - 3 }, obstacles);
  if (!position) return;
  reward.style.left = `${position.left - source.left}px`;
  reward.style.top = `${position.top - source.top}px`;
  reward.style.bottom = 'auto';
  reward.style.setProperty('--replay-reward-base-x', '0%');
  reward.style.setProperty('--replay-reward-base-y', '0%');
  badge.dataset.rewardDirection = 'placed';
}
